"app-grove": {"hero": "grove", "accent": "#223829", "mark": {"tree": "grove", "name": "The Grove"}, "video": {"id": "pv-app-grove", "title": "The Grove", "blurb": "Where our trees grow together, for families and groups.", "scenes": [{"k": "title", "hero": "grove", "eyebrow": "The Grove", "h": "The Grove", "sub": "Your tree is yours. The grove is ours.", "say": "This is The Grove, where our trees grow together. Your tree is yours. The grove is ours."}, {"k": "big", "h": "Growing side by side.", "sub": "All ages. All stages.", "say": "Families and groups go through a lot together. The Grove gives you one place to check in, and to grow side by side."}, {"k": "points", "h": "Choose your kind", "items": [["Family", "A household, or family across homes"], ["Faith Community", "A congregation or a study class"], ["Small or Discussion Group", "A support group or a study group"], ["Team or Workplace", "People who work side by side"]], "say": "Choose your kind. Family. Faith Community. Small or Discussion Group. Or Team or Workplace.", "cue": {"at": [1, 2, 3, 4]}}, {"k": "flow", "h": "How every grove grows", "steps": [["Check in together", "One shared answer"], ["Make a Growth Plan", "Two or three practices"], ["Do them together", "And the grove grows"]], "say": "Check in together, and settle on one shared answer for each question. Make a Growth Plan with two or three practices. Then do them side by side.", "cue": {"at": [0, 1, 2]}}, {"k": "big", "h": "Results in words.", "sub": "The Grove keeps only the answers you share together.", "say": "Results come in words, and The Grove keeps only the answers you share together."}, {"k": "words", "h": "One word each", "items": ["How are you arriving today?", "One word is enough."], "beats": ["Let's try it now.", {"t": "Look around at who is with you, and each person, say one word for how you are arriving today.", "w": 10}], "say": "Let's try it now. Look around at who is with you, and each person, say one word for how you are arriving today."}, {"k": "points", "h": "More together", "items": [["Together", "Practices to do side by side"], ["When Life Changes", "Guides for changes you go through together"], ["Learn", "Short videos for everyone watching"]], "say": "Together has practices to do side by side. When Life Changes has guides for the changes you face together. And Learn has short videos for everyone.", "cue": {"at": [0, 1, 2]}}, {"k": "big", "h": "Locked with a grove passcode.", "sub": "On this device only.", "say": "Everything is locked with a grove passcode, on this device only."}, {"k": "big", "h": "Tap Visit our grove.", "sub": "Choose your kind, and begin.", "say": "Ready? Tap Visit our grove, choose your kind, and begin."}], "mins": 2, "n": 1, "sources": [], "audio": "pv"}, "next": [{"label": "Visit our grove", "t": "Visit our grove"}]},
"the-grounded-way": {"hero": "page-grounded-way", "accent": "#5F7D48", "mark": {"name": "The Grounded Way"}, "next": [{"label": "Open The Grounded Way", "t": "Open The Grounded Way"}], "video": {"id": "pv-the-grounded-way", "title": "The Grounded Way", "blurb": "What The Grounded Way is, its four tabs, what Tending holds, and how to begin.", "mins": 3, "n": 1, "audio": "pv", "crisis": ["Call or text 988, any time", "In an emergency, call 911"], "sources": ["tend-aha-satfat", "tend-aha-sugar", "tend-aha-sodium", "way-aha-fish", "tend-dga", "tend-predimed", "tend-pag"], "scenes": [{"k": "title", "hero": "page-grounded-way", "eyebrow": "The All-In Path", "h": "The Grounded Way", "sub": "Built to thrive in mind, body, spirit, and relationships.", "say": "This is The Grounded Way. In about three minutes, here is what it is, what Tending holds, and how to begin."}, {"k": "big", "bg": "page-grounded-way", "h": "Built to thrive.", "sub": "Mind, body, spirit, and relationships.", "say": "The trees are open to everyone. The Grounded Way is for people who want to go all in, and live the Grounded way every day. It is built to thrive, in mind, body, spirit, and relationships."}, {"k": "points", "h": "What Tending holds", "items": [["My Grounded Way Plan", "One plan from your Growing Edges"], ["Movement for Every Level", "Strength, Cardio, Flow, Yoga, Balance, Stretch"], ["Grounded Recipes", "Every meal sized for your table"], ["Quiet and Meditation", "Morning Quiet and seven guided meditations"], ["Your Numbers", "Labs, the LDL Path, and My Heart Risk"]], "say": "Tending holds the everyday together. My Grounded Way Plan builds one plan from your check-in's Growing Edges, for body, mind, spirit, and the table. Movement for every level, in six kinds: Strength, Cardio, Flow, Yoga, Balance, and Stretch. Grounded Recipes, with every meal sized for your table, one shopping list, and family nutrition that tracks the food, never the body. Morning Quiet, and seven guided meditations on painted scenes. And your own numbers, with labs, the LDL Path, and My Heart Risk.", "cue": {"at": [1, 2, 3, 4, 5]}}, {"k": "points", "h": "The Grounded Nutritional Standards", "items": [["Whole food", "On a Mediterranean base"], ["Half the plate", "Vegetables or fruit"], ["Whole grains", "With olive or avocado oil"], ["Fish twice a week", "Lean red meat once a week at most"], ["Sweetness from fruit first", "Simple, whole ingredients"]], "say": "Every recipe meets the Grounded Nutritional Standards. It starts from whole food, on a Mediterranean base. Half the plate is vegetables or fruit, with whole grains and olive or avocado oil. Fish comes twice a week or more, and lean red meat once a week at most. Sweetness comes from fruit first, in simple, whole ingredients.", "cue": {"at": [1, 2, 2, 3, 4]}}, {"k": "levels", "levels": [["Root", "Begin here", "#7A4E2A"], ["Rise", "Build strength", "#5F7D48"], ["Thrive", "Go further", "#3A6B35"], ["Gentle", "A softer start", "#4F7A9A"]], "say": "Movement begins with a short check. Then choose Root, Rise, or Thrive, or the Gentle path, with chair strength, supported balance, and short walks. Pick home, light weights, or a full gym, in twenty, forty, or sixty minutes. The 12-Week Program grows through Foundation, Build, and Peak, and a calm coach counts every rep, with a figure moving inside a Grounded painting."}, {"k": "breathe", "h": "One slow breath", "sub": "In for four. Out for six.", "beats": ["Let's pause together.", {"t": "Sit tall, and take one slow breath, in for four, and out for six.", "w": 10}, "That is how a good day begins."], "say": "Let's pause together. Sit tall, and take one slow breath, in for four, and out for six. That is how a good day begins."}, {"k": "big", "h": "Private by design.", "sub": "On your device, locked with your passcode.", "say": "Everything in Tending stays on your own device, locked with your own passcode. It offers guidance, with research-informed estimates shown as ranges, made to talk over with your doctor."}, {"k": "big", "bg": "page-grounded-way", "h": "Open The Grounded Way", "sub": "Today, Week, Grow, and Library.", "say": "To begin, tap Open The Grounded Way. Today, Week, Grow, and Library bring your tree and Tending together in one private app, built for the way you want to live."}]}}
